import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.DuPBmefI.js";const i=JSON.parse('{"title":"德望学校 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-4b0457f5","school_zh":"德望学校","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"德望学校 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["HOT22-GHS"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-4b0457f5/s1/unknown-interview.md","filePath":"reports/school-4b0457f5/s1/unknown-interview.md"}'),n={name:"reports/school-4b0457f5/s1/unknown-interview.md"};function p(a,o,l,c,g,h){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="德望学校-·-年份未注明-·-中一-·-面试" tabindex="-1">德望学校 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#德望学校-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;德望学校 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-4b0457f5">← 返回德望学校资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-hot22-ghs" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-ghs" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-ghs}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>生活与个人经历</strong></p><p>怎样收拾玩具；有无兄弟姐妹、一起做什么；为什么女孩喜欢娃娃、男孩喜欢玩具枪；有兄弟姐妹是否更快乐；欣赏谁、难忘经历；若今天没有面试会做什么；体育课做什么、是否喜欢。</p><p><strong>朗读与填空</strong></p><p>阅读文章并完成填空。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>家庭与校园</strong></p><p>最喜欢香港哪个主题乐园；家庭或学校哪一方影响较大；用一个形容词形容家庭或学校。</p><p><strong>语文与历史常识</strong></p><p>“近朱者赤”的“朱”是什么颜色；“闻鸡起舞”涉及哪位历史人物；“抱薪救火”的“薪”是什么意思；中国最后一个朝代；唐玄宗宠爱谁；“养不教”的下一句。</p><p><strong>时事与学校认识</strong></p><p>回答当时台湾地区领导人、香港行政长官是谁，以及学校宗教背景和地址。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>限时计算</strong></p><p>10分钟40题，例题包括178－16×4和求图形面积；另有三道奥数式题目的形式。</p><p><strong>水果应用题</strong></p><p>一个苹果重3克、一个橙重8克，篮子现重56克，问苹果及橙各有多少个，须写出计算过程。是否包含篮子重量等条件未明确。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 普通话</p><p><strong>活动策划</strong></p><p>8人一组：作为中文学会成员策划活动；担任健康推广员如何利用午膳时间开展活动；义工组探访儿童并送上祝福；是否应在小息用5分钟做课间操。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 英语</p><p><strong>校服意见</strong></p><p>是否喜欢自己的校服，为什么。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>小组讨论：</strong> 英语</p><p><strong>校园与未来</strong></p><p>未来想成为什么样的人；最喜欢的老师及原因；是否喜欢以裙子作校服；希望取消哪一条校规；喜欢小学哪一部分、最喜欢什么科目。</p><p><strong>申请与平衡</strong></p><p>如何平衡功课与课外活动；为何申请德望；还申请哪些学校。</p></blockquote><blockquote><p><strong>家长与学生面谈：</strong> 部分粤语</p><p><strong>教育期望</strong></p><p>家长谈对德望的看法、孩子在家的活动（粤语）、希望女儿在校学到什么及其优缺点；学生回答是否同意父母的描述。</p></blockquote>',16)])])}const d=t(n,[["render",p]]);export{i as __pageData,d as default};
